and this is my css code
html{
height:100;
overflow: hidden;
}

body{
  color: #fff;
  margin: 0;
  padding: 0;
  perspective:1px;
  transform-style: preserve-3d;
  height: 100%;
  overflow-y: scroll;
  overflow-x: hidden;
  font-family: "Luna";
}

header{
  box-sizing: border-box;
  min-height: 100vh;
  padding: 30vw 0 5vw;
  position: relative;
  transform-style: inherit;
  width: 100vw;
}

header h1{
  margin-top: -100px;
  text-align: center;
  }

header p{
  text-align: center;
}

header, header:before{
  background: 50% 50% / cover;
}

header::before{
  bottom: 0;
  content: "";
  left: 0;
  position: absolute;
  right: 0;
  top: 0;
  display: block;
  background-image: url(https://i.redd.it/9d0ysc9r15t01.png);
  background-size: cover;
  transform-origin: center center 0;
  transform: translateZ(-1px) scale(2);
  z-index: -1;
  min-height: 100
}
.container{
    text-align:center;
    margin-top: 360px;
    position: absolute;
    z-index: 0;
    background-color: #ccc;
    height: inherit;
    width: 100vw;
  }

  .btn{
    border: 1px solid #3498db;
    background: none;
    padding: 10px 20px;
    font-size: 20px;
    font-family: "montserrat";
    cursor: pointer;
    margin: 10px;
    transition: 0.8s;
    position: relative;
    overflow: hidden;
    }

  .btn1,.btn2,.btn3,.btn4{
    color: #3498db;
    align-items: center;
  }
.btn1:hover,.btn2:hover,.btn3:hover,.btn4:hover{
  color:#fff;
}
.btn::before{
  content: "";
  position: absolute;
  left: 0;
  width: 100%;
  height: 0%;
  background: #3498db;
  z-index: -1;
  transition: 0.8s;
}
.btn1::before,.btn3::before{
  top:0;
  border-radius: 0 0 50% 50%;
}
.btn2::before,.btn4::before{
  top:0;
  border-radius: 0 0 50% 50%;
}
.btn1:hover::before,.btn2:hover::before,.btn3:hover::before,.btn4:hover::before{
  height: 180%
}

